// Auth + parse + classify (spec §3.3 access control, §4.1).
const item = $input.first().json;
const headers = item.headers || {};
const body = item.body || {};
const ticket_id = (item.params && item.params.id) || body.ticket_id;
const roleKey = headers['x-fsc-role-key'];
const actor = body.actor || '';
const role = actor.split(':')[0]; // 'technician' | 'supervisor'

const KEYS = { technician: $env.FSC_ROLE_KEY_TECHNICIAN, supervisor: $env.FSC_ROLE_KEY_SUPERVISOR };
if (!ticket_id) return [{ json: { __error: { code: 'VALIDATION_FAILED', message: 'Falta ticket_id.' }, __status: 422 } }];
if (!role || !KEYS[role] || roleKey !== KEYS[role])
  return [{ json: { __error: { code: 'FORBIDDEN', message: 'Clave de rol no válida.' }, __status: 403 } }];

return [{ json: { ticket_id, role, actor, to_status: body.to_status, eta: body.eta || null, assigned_technician: body.assigned_technician || null, priority: body.priority || null, note: body.note || null } }];

// Validate legal edge (spec §6.2) + build atomic patch (§6.1) + pick notify template (§7).
const req = $('Auth & Parse').first().json;
const ticket = $input.first().json; // current ticket from datastore

const LEGAL = {
  'Intake':      { 'Triage': ['supervisor'] },
  'Triage':      { 'Dispatch': ['supervisor'] },
  'Dispatch':    { 'On the way': ['technician','supervisor'] },
  'On the way':  { 'On site': ['technician','supervisor'] },
  'On site':     { 'Close': ['technician','supervisor'] },
  'Close':       { 'Triage': ['supervisor'] } // reopen
};
const from = ticket.status;
const to = req.to_status;
const allowedRoles = (LEGAL[from] || {})[to];
if (!allowedRoles)
  return [{ json: { __error: { code: 'ILLEGAL_TRANSITION', message: `No se permite ${from} → ${to}.` }, __status: 409 } }];
if (!allowedRoles.includes(req.role))
  return [{ json: { __error: { code: 'FORBIDDEN', message: `El rol ${req.role} no puede ${from} → ${to}.` }, __status: 403 } }];

// Edge-specific required-field checks
const now = new Date().toISOString();
const patch = { status: to, updated_at: now };
if (to === 'Triage') patch.priority = req.priority || ticket.priority || 'normal';
if (to === 'Dispatch') {
  if (!req.assigned_technician) return [{ json: { __error: { code: 'VALIDATION_FAILED', message: 'assigned_technician es obligatorio para Dispatch.', fields: { assigned_technician: 'Obligatorio.' } }, __status: 422 } }];
  patch.assigned_technician = req.assigned_technician;
  if (req.eta) patch.eta = req.eta;
}
if (to === 'On the way') {
  const eta = req.eta || ticket.eta;
  if (!eta || new Date(eta).getTime() < Date.now() - 60000)
    return [{ json: { __error: { code: 'VALIDATION_FAILED', message: 'eta válida (>= ahora) es obligatoria para On the way.', fields: { eta: 'Obligatoria y futura.' } }, __status: 422 } }];
  patch.eta = eta;
}
if (to === 'Triage' && from === 'Close') { patch.assigned_technician = null; patch.eta = null; } // reopen reset

// Notify template map (only boundaries that notify — §7.1)
const TPL = { 'Dispatch': 'T2', 'On the way': 'T3', 'On site': 'T4', 'Close': 'T5' };
const EVT = { 'Triage': 'fsc.v1.ticket.triaged', 'Dispatch': 'fsc.v1.ticket.dispatched', 'On the way': 'fsc.v1.ticket.enroute', 'On site': 'fsc.v1.ticket.onsite', 'Close': 'fsc.v1.ticket.closed' };

const audit = (ticket.audit_log || []).concat([{ at: now, actor: req.actor, from_status: from, to_status: to, note: req.note || null }]);
const updated = Object.assign({}, ticket, patch, { audit_log: audit });

return [{ json: { updated, event_name: EVT[to], notify_template: TPL[to] || null } }];

// Emit domain event (spec §4.2). Notification is decoupled & may fail without rollback (§7.5).
const v = $('Validate edge & build patch').first().json;
return [{ json: {
  event: v.event_name,
  ticket_id: v.updated.ticket_id,
  occurred_at: new Date().toISOString(),
  actor: v.updated.audit_log[v.updated.audit_log.length - 1].actor,
  data: v.updated,
  notify_template: v.notify_template
} }];
